import os
from datetime import datetime

# Ensure we have the source file list
vac_dir = '~/photographs/vacations/'
try:
    source_files = res  # from prior show_directory
except NameError:
    source_files = apis.file_system.show_directory(directory_path=vac_dir, access_token=token, entry_type='files', recursive=False)

print('source_files_count', len(source_files))

this_year = datetime.now().year
print('this_year', this_year)

def get_created_at_month_year(path):
    info = apis.file_system.show_file(file_path=path, access_token=token)
    created_at = info.get('created_at')
    if not created_at:
        return None, None
    dt = datetime.fromisoformat(created_at)
    return dt.month, dt.year

categories = {'Rome': [], 'Santorini': [], 'Berlin': []}

for p in source_files:
    m, y = get_created_at_month_year(p)
    if y == this_year and m == 3:
        categories['Rome'].append(p)
    elif y == this_year and m == 4:
        categories['Santorini'].append(p)
    else:
        categories['Berlin'].append(p)

for k,v in categories.items():
    print(k, 'count', len(v))

# Print a few examples per category to sanity check
for k,v in categories.items():
    print('---', k)
    for ex in v[:3]:
        info = apis.file_system.show_file(file_path=ex, access_token=token)
        print(os.path.basename(ex), info.get('created_at'))

